// Browser-compatible cipher helpers for user profile data security in Firestore database
export function encryptData(val: string): string {
  if (!val) return "";
  const trimmed = String(val).trim();
  if (trimmed.startsWith("ENC:")) return trimmed;
  // Shift character codes (+3) and base64 encode
  const shifted = trimmed.split("").map(c => String.fromCharCode(c.charCodeAt(0) + 3)).join("");
  try {
    return "ENC:" + btoa(unescape(encodeURIComponent(shifted)));
  } catch (err) {
    return "ENC:" + shifted;
  }
}

export function decryptData(encryptedVal: string): string {
  if (!encryptedVal) return "";
  const trimmed = String(encryptedVal).trim();
  if (!trimmed.startsWith("ENC:")) return trimmed; // Plain text / non-encrypted data compatibility
  
  const payload = trimmed.slice(4); // remove "ENC:"
  try {
    let rawShifted = "";
    try {
      rawShifted = decodeURIComponent(escape(atob(payload)));
    } catch {
      rawShifted = payload;
    }
    return rawShifted.split("").map(c => String.fromCharCode(c.charCodeAt(0) - 3)).join("");
  } catch (err) {
    console.error("Failed to decrypt field value:", err);
    return String(encryptedVal);
  }
}

// Aliases for mobile encryption compatibility
export const encryptMobile = encryptData;
export const decryptMobile = decryptData;

// Highly efficient client-side image compression using canvas (Optimized for crystal-clear HD resolution and Firestore safety limits)
export function compressImage(
  file: File, 
  maxWidth: number = 1200, 
  maxHeight: number = 1200, 
  quality: number = 0.90,
  forceSquareCrop: boolean = false
): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = (event) => {
      const img = new Image();
      img.src = event.target?.result as string;
      img.onload = () => {
        let currentWidth = img.width;
        let currentHeight = img.height;
        let currentQuality = quality;
        let currentMaxWidth = maxWidth;
        let currentMaxHeight = maxHeight;

        const performCompression = (): string => {
          const canvas = document.createElement("canvas");
          const ctx = canvas.getContext("2d");
          if (!ctx) {
            return event.target?.result as string;
          }

          let w = currentWidth;
          let h = currentHeight;

          if (forceSquareCrop) {
            // Center-crop to a perfect square to prevent squashing or stretching
            const size = Math.min(w, h);
            const sx = (currentWidth - size) / 2;
            const sy = (currentHeight - size) / 2;
            
            // Target square size (Ensure a minimum size of 450px with smooth resampling if the uploaded image is small)
            const targetSize = Math.max(Math.min(size, currentMaxWidth), Math.min(450, size));
            canvas.width = targetSize;
            canvas.height = targetSize;

            // Paint solid white background to avoid transparent black blocks on PNGs during JPEG output
            ctx.fillStyle = "#ffffff";
            ctx.fillRect(0, 0, targetSize, targetSize);

            ctx.imageSmoothingEnabled = true;
            ctx.imageSmoothingQuality = "high";
            ctx.drawImage(img, sx, sy, size, size, 0, 0, targetSize, targetSize);
          } else {
            // Smart proportional downscaling while maintaining aspect ratio and high definition
            if (w > h) {
              if (w > currentMaxWidth) {
                h = Math.round((h * currentMaxWidth) / w);
                w = currentMaxWidth;
              }
            } else {
              if (h > currentMaxHeight) {
                w = Math.round((w * currentMaxHeight) / h);
                h = currentMaxHeight;
              }
            }

            canvas.width = w;
            canvas.height = h;

            // Paint solid white background
            ctx.fillStyle = "#ffffff";
            ctx.fillRect(0, 0, w, h);

            ctx.imageSmoothingEnabled = true;
            ctx.imageSmoothingQuality = "high";
            ctx.drawImage(img, 0, 0, w, h);
          }

          // Compress as high-fidelity image/jpeg
          return canvas.toDataURL("image/jpeg", currentQuality);
        };

        let result = performCompression();
        let attempts = 0;
        // Firestore maximum document size is 1MB. Keep single image base64 under 450KB so that multiple images (or a single image + comments) never break the limit.
        const maxCharacters = 450000; 

        while (result.length > maxCharacters && attempts < 10) {
          attempts++;
          // Reduce dimensions by 15% and quality by 15% on each pass to rapidly and smoothly downscale
          currentMaxWidth = Math.round(currentMaxWidth * 0.82);
          currentMaxHeight = Math.round(currentMaxHeight * 0.82);
          currentQuality = Math.max(0.35, currentQuality * 0.82);
          result = performCompression();
        }

        resolve(result);
      };
      img.onerror = (err) => reject(err);
    };
    reader.onerror = (err) => reject(err);
  });
}

// Check if a user's security shield is active (based on from/to dates)
export function isUserSecured(usr: { isSecured?: boolean; securityFromDate?: string | null; securityToDate?: string | null } | null | undefined): boolean {
  if (!usr) return false;
  if (!usr.isSecured) return false;
  const nowStr = new Date().toISOString().split("T")[0]; // YYYY-MM-DD format
  if (usr.securityFromDate && nowStr < usr.securityFromDate) {
    return false;
  }
  if (usr.securityToDate && nowStr > usr.securityToDate) {
    return false;
  }
  return true;
}

// Check if a user's gold/boosted premium rank is active (based on from/to dates)
export function isUserGold(usr: { isGoldMember?: boolean; boostFromDate?: string | null; boostToDate?: string | null } | null | undefined): boolean {
  if (!usr) return false;
  if (!usr.isGoldMember) return false;
  const nowStr = new Date().toISOString().split("T")[0]; // YYYY-MM-DD format
  if (usr.boostFromDate && nowStr < usr.boostFromDate) {
    return false;
  }
  if (usr.boostToDate && nowStr > usr.boostToDate) {
    return false;
  }
  return true;
}

// Check if a user is a verified business account
export function isUserBusiness(usr: { isBusiness?: boolean; businessVerified?: boolean; accountType?: string } | null | undefined): boolean {
  if (!usr) return false;
  return !!usr.isBusiness || usr.accountType === "business";
}

