export const isSuperAdmin = (email?: string | null, profile?: UserProfile | null): boolean => {
  if (!email && !profile) return false;
  const e = (email || profile?.email || "").toLowerCase().trim();
  if (SUPER_ADMIN_EMAILS.includes(e)) return true;
  return !!(profile?.isSuperAdmin || (profile?.isAdmin && !profile?.isStoreGigAdmin));
};

export const isSystemAdmin = (email?: string | null, profile?: UserProfile | null): boolean => {
  if (!email && !profile) return false;
  const e = (email || profile?.email || "").toLowerCase().trim();
  if (ADMIN_EMAILS.includes(e)) return true;
  return !!(profile?.isAdmin || profile?.isSuperAdmin || profile?.isStoreGigAdmin);
};

export const isStoreGigAdmin = (email?: string | null, profile?: UserProfile | null): boolean => {
  const e = (email || profile?.email || "").toLowerCase().trim();
  return STORE_GIG_ADMIN_EMAILS.includes(e) || !!profile?.isStoreGigAdmin;
};

